<template>
  <SafetyManagementShell :title="isWeekly?'每周安全生产排查报告':'每月安全生产工作调度会议纪要'" :subtitle="isWeekly?'默认周一至周日统计，保留实际排查时间':'自然月统计，会议讨论与决议由实际参加人员填写'">
    <view class="sm-stack"><view class="sm-card"><view class="sm-section-head"><text class="sm-h2">{{ isWeekly?'选择所属周':'选择统计月份' }}</text><text class="sm-tag sm-tag--warn">待签认</text></view><picker v-if="isWeekly" mode="date" :value="selectedDate" @change="changePeriod($event.detail.value)"><view class="sm-picker">{{ selectedDate }} 所在周 ▾</view></picker><picker v-else mode="date" fields="month" :value="selectedMonth" @change="changePeriod($event.detail.value)"><view class="sm-picker">{{ selectedMonth }} ▾</view></picker></view>
      <view v-if="loading" class="sm-state">正在读取统计来源与已保存材料…</view><view v-else-if="error" class="sm-alert sm-alert--error">{{ error }}<button class="sm-btn sm-btn--secondary" @click="load">重试</button></view>
      <template v-else><view v-if="revisionConflict" class="sm-alert sm-alert--error">当前台账已被其他操作保存为新版本。你的编辑仍保留，请复制需要保留的内容，再重新加载并合并。<button class="sm-btn sm-btn--secondary sm-btn--small" @click="reloadContent">重新加载台账内容</button></view><view v-if="sourceConflict" class="sm-alert">统计来源已变化，你的编辑仍保留。请刷新来源统计，核对变化并调整内容后保存。</view><view v-if="report.stale" class="sm-alert">来源统计已有变化，请核对后填写修订原因并保存新版本。原记录保留。</view><view v-if="!canEdit" class="sm-alert sm-alert--info">当前账号可查看本台账；{{ isWeekly?'周排查由实际配置的安全总监填写。':'月调度由实际配置的主要负责人填写。' }}</view>
        <SafetyStatistics :statistics="report.statistics || {}" :period="report.period || {}" />
        <view class="sm-alert sm-alert--info">统计和来源材料供核对引用。{{ isWeekly?'现场排查、执行评价和下周计划':'实际会议、讨论判断和决议' }}均需据实填写，保存草稿不代表已{{ isWeekly?'组织排查':'召开会议' }}或已签认。</view>
        <view v-if="report.previous?.content || report.previous?.record?.content" class="sm-card"><text class="sm-h2">{{ isWeekly?'上周排查材料':'上月决议与落实材料' }}</text><template v-if="!isWeekly"><view v-for="(decision,index) in previousContent.decisions || []" :key="index" class="sm-list-row"><text class="sm-h3">{{ decision.subject }}</text><text class="sm-text">{{ decision.department }} · {{ decision.responsible_name }} · {{ decision.due_date }}</text><text class="sm-help">{{ decision.implementation || '尚未填写落实情况' }}</text></view><text class="sm-help">请在下方“上月决议落实情况”填写本次真实核验结果。</text></template><text v-else class="sm-text">{{ previousContent.next_plan || '上期没有下周计划材料' }}</text></view>
        <view class="sm-card"><text class="sm-h2">{{ isWeekly?'实际排查信息':'实际会议信息' }}</text><view class="sm-grid"><view class="sm-field"><text class="sm-field-label">{{ isWeekly?'实际排查日期':'实际会议日期' }}</text><picker mode="date" :value="content.actual_date" :disabled="!canEdit" @change="content.actual_date=$event.detail.value"><view class="sm-picker">{{ content.actual_date || '按实际发生日期选择' }}</view></picker></view><label v-for="field in identityFields" :key="field.key" class="sm-field"><text class="sm-field-label">{{ field.label }}</text><input v-model="content[field.key]" class="sm-input" :disabled="!canEdit" :placeholder="field.placeholder || '据实填写'" maxlength="500" /></label><label class="sm-field"><text class="sm-field-label">实际开始时间（北京时间）</text><input v-model="content.started_at" class="sm-input" :disabled="!canEdit" placeholder="YYYY-MM-DD HH:mm" /></label><label class="sm-field"><text class="sm-field-label">实际结束时间（北京时间）</text><input v-model="content.ended_at" class="sm-input" :disabled="!canEdit" placeholder="YYYY-MM-DD HH:mm" /></label></view><label class="sm-field"><text class="sm-field-label">实际参加人员</text><textarea v-model="content.participants" class="sm-textarea" :disabled="!canEdit" placeholder="填写实际到场人员姓名、岗位" maxlength="10000" /></label><label v-if="!isWeekly" class="sm-field"><text class="sm-field-label">缺席人员及原因</text><textarea v-model="content.absences" class="sm-textarea" :disabled="!canEdit" placeholder="按实际情况填写" /></label></view>
        <view v-for="field in narrativeFields" :key="field.key" class="sm-card"><text class="sm-h2">{{ field.label }}</text><text v-if="field.help" class="sm-help">{{ field.help }}</text><label class="sm-field"><textarea v-model="content[field.key]" class="sm-textarea sm-textarea--large" :disabled="!canEdit" :placeholder="field.placeholder || '请填写实际检查、讨论和核验情况；没有发生的事项也需明确说明'" maxlength="10000" /></label></view>
        <template v-if="isWeekly"><view class="sm-card"><view class="sm-section-head"><text class="sm-h2">管理问题与改进措施</text><button v-if="canEdit" class="sm-btn sm-btn--secondary sm-btn--small" @click="addManagementIssue">添加问题</button></view><text class="sm-help">此处“问题风险等级”为一般 / 较大 / 重大，与现场隐患的“一般 / 重大”分别记录。</text><view v-for="(issue,index) in content.management_issues" :key="index" class="sm-list-row"><view class="sm-section-head"><text class="sm-h3">管理问题 {{ index+1 }}</text><button v-if="canEdit" class="sm-btn sm-btn--secondary sm-btn--small" @click="content.management_issues.splice(index,1)">移除</button></view><view class="sm-grid"><label class="sm-field"><text class="sm-field-label">问题类型</text><input v-model="issue.type" class="sm-input" :disabled="!canEdit" placeholder="制度、培训、投入、管理等" /></label><view class="sm-field"><text class="sm-field-label">问题风险等级</text><view class="sm-options"><view v-for="risk in riskLevels" :key="risk.value" :class="['sm-option',{'sm-option--active':issue.risk_level===risk.value}]" @click="canEdit && (issue.risk_level=risk.value)">{{ risk.label }}</view></view></view></view><label class="sm-field"><text class="sm-field-label">问题描述</text><textarea v-model="issue.description" class="sm-textarea" :disabled="!canEdit" /></label><label class="sm-field"><text class="sm-field-label">实际改进措施</text><textarea v-model="issue.measure" class="sm-textarea" :disabled="!canEdit" /></label><view class="sm-grid"><label class="sm-field"><text class="sm-field-label">责任人</text><input v-model="issue.responsible_name" class="sm-input" :disabled="!canEdit" /></label><view class="sm-field"><text class="sm-field-label">期限</text><picker mode="date" :value="issue.due_date" :disabled="!canEdit" @change="issue.due_date=$event.detail.value"><view class="sm-picker">{{ issue.due_date || '选择日期' }}</view></picker></view></view></view></view>
          <view class="sm-card"><text class="sm-h2">周排查新发现或复见的现场隐患</text><text class="sm-help">现场隐患进入共同整改台账，管理问题保留上面的单独记录。隐患可先登记，再完善本报告。</text><text v-if="content.hazard_ids?.length" class="sm-text">已关联：{{ content.hazard_ids.join('、') }}</text><view v-if="canEdit" class="sm-field"><text class="sm-field-label">新问题主分类</text><picker :range="categories" range-key="name" :value="issueCategoryIndex" @change="issueCategoryIndex=Number($event.detail.value)"><view class="sm-picker">{{ categories[issueCategoryIndex]?.name || '选择主分类' }}</view></picker></view><button v-if="canEdit && !showIssue" class="sm-btn sm-btn--secondary" @click="showIssue=true">立即登记 / 关联现场隐患</button><SafetyIssueEditor v-if="showIssue" :date="content.actual_date || selectedDate" source-type="weekly" :source-item-code="`weekly-${report.period?.start_date || selectedDate}`" :source-id="report.record?._id || ''" :source-period-start="report.period?.start_date || ''" :category="Number(categories[issueCategoryIndex]?.id || 7)" :hazards="report.statistics?.historical_pending || []" @saved="issueSaved" @cancel="showIssue=false" /></view>
        </template>
        <view v-else class="sm-card"><view class="sm-section-head"><text class="sm-h2">本月会议决议</text><button v-if="canEdit" class="sm-btn sm-btn--secondary sm-btn--small" @click="addDecision">添加事项</button></view><text class="sm-help">每项单独明确责任部门、责任人和期限，落实情况将供下月引用。</text><view v-for="(decision,index) in content.decisions" :key="index" class="sm-list-row"><view class="sm-section-head"><text class="sm-h3">决议 {{ index+1 }}</text><button v-if="canEdit" class="sm-btn sm-btn--secondary sm-btn--small" @click="content.decisions.splice(index,1)">移除</button></view><label class="sm-field"><text class="sm-field-label">实际决议事项</text><textarea v-model="decision.subject" class="sm-textarea" :disabled="!canEdit" /></label><view class="sm-grid"><label class="sm-field"><text class="sm-field-label">责任部门</text><input v-model="decision.department" class="sm-input" :disabled="!canEdit" /></label><label class="sm-field"><text class="sm-field-label">责任人</text><input v-model="decision.responsible_name" class="sm-input" :disabled="!canEdit" /></label><view class="sm-field"><text class="sm-field-label">完成期限</text><picker mode="date" :value="decision.due_date" :disabled="!canEdit" @change="decision.due_date=$event.detail.value"><view class="sm-picker">{{ decision.due_date || '选择日期' }}</view></picker></view><view class="sm-field"><text class="sm-field-label">落实状态</text><picker :range="decisionStatuses" range-key="label" :value="decisionStatuses.findIndex(item=>item.value===decision.status)" :disabled="!canEdit" @change="decision.status=decisionStatuses[Number($event.detail.value)].value"><view class="sm-picker">{{ decisionStatuses.find(item=>item.value===decision.status)?.label || '待落实' }}</view></picker></view></view><label class="sm-field"><text class="sm-field-label">实际落实情况及证据引用</text><textarea v-model="decision.implementation" class="sm-textarea" :disabled="!canEdit" /></label></view></view>
        <SafetyRevisionHistory :kind="kind" :record-id="report.record?._id" />
        <view class="sm-card"><text class="sm-h2">保存与修订</text><text class="sm-text">当前版本：{{ report.record?.revision || 0 }} · {{ report.record?.content_status==='complete'?'内容完整':'草稿 / 待完善' }} · 待签认</text><label v-if="canEdit" class="sm-field"><text class="sm-field-label">{{ report.record?'本次修订原因 *':'保存说明' }}</text><textarea v-model="revisionReason" class="sm-textarea" placeholder="说明实际补充的事实、修正依据或统计变化" /></label><view class="sm-actions"><button v-if="canEdit" class="sm-btn" :disabled="saving || revisionConflict" @click="save">{{ saving?'保存中…':'保存台账内容' }}</button><button class="sm-btn sm-btn--secondary" @click="refreshSources">刷新来源统计</button><button class="sm-btn sm-btn--secondary" @click="preview">打印预览 / 保存 PDF</button><button v-if="report.permissions?.export" class="sm-btn sm-btn--secondary" :disabled="exporting" @click="exportExcel">{{ exporting?'正在生成…':'导出 Excel' }}</button></view><text class="sm-help">未完成内容可保存草稿，导出明确标记未完成与待签认。未保存编辑不包含在导出中。</text></view>
      </template>
    </view>
  </SafetyManagementShell>
</template>
<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import SafetyManagementShell from './SafetyManagementShell.vue'
import SafetyStatistics from './SafetyStatistics.vue'
import SafetyIssueEditor from './SafetyIssueEditor.vue'
import SafetyRevisionHistory from './SafetyRevisionHistory.vue'
import { getSafetyConfig,getSafetyWeekly,saveSafetyWeekly,getSafetyMonthly,saveSafetyMonthly,exportSafetyDocument } from '@/services/safetyManagement'
import { beijingDate,clone,downloadFile,openSafetyPage,showError } from './helpers'
const props=defineProps({kind:{type:String,default:'weekly'},date:{type:String,default:''},month:{type:String,default:''}})
const isWeekly=computed(()=>props.kind==='weekly'),selectedDate=ref(props.date || beijingDate()),selectedMonth=ref(props.month || beijingDate().slice(0,7)),loading=ref(true),error=ref(''),saving=ref(false),exporting=ref(false),report=ref({}),content=ref({}),revisionReason=ref(''),showIssue=ref(false),issueCategoryIndex=ref(0),categories=ref([]),editBaseline=ref(''),editRevision=ref(0),editFingerprint=ref(''),sourceConflict=ref(false)
const revisionConflict=computed(()=>(report.value.record?.revision || 0)!==editRevision.value)
const canEdit=computed(()=>Boolean(report.value.permissions?.[props.kind])),previousContent=computed(()=>report.value.previous?.content || report.value.previous?.record?.content || {})
const identityFields=computed(()=>isWeekly.value?[{key:'organizer',label:'实际组织人'}]:[{key:'title',label:'会议名称'},{key:'location',label:'会议地点'},{key:'host',label:'主持人'},{key:'recorder',label:'记录人'}])
const weeklyNarratives=[{key:'scope',label:'排查范围与依据',help:'专业清单、维护保养、技术档案、检验校验和培训等按适用性核验。'},{key:'site_findings',label:'实际现场排查结果',help:'紧急切断、联锁、报警等核验定期调试证据，不要求每周都进行动作试验。'},{key:'execution_evaluation',label:'日管控执行质量评价',help:'对实际巡检、日表缺项、证据质量和隐患闭环作出实际评价。'},{key:'repeated_problem_analysis',label:'反复问题与原因分析'},{key:'system_gaps',label:'制度漏洞与改进措施'},{key:'next_plan',label:'下周工作计划'}]
const monthlyNarratives=[{key:'previous_decisions',label:'上月决议落实情况'},{key:'accidents_and_near_misses',label:'事故及涉险情况'},{key:'safety_situation',label:'安全形势与日、周工作执行情况'},{key:'major_risks',label:'重大风险和重大隐患'},{key:'special_work',label:'专项工作开展情况'},{key:'training',label:'教育培训与人员配置'},{key:'expenditure',label:'安全费用与投入保障'},{key:'emergency_management',label:'应急管理、预案与演练'},{key:'contractors',label:'外协管理'},{key:'causes',label:'问题原因与改进分析'},{key:'principal_summary',label:'主要负责人总结及工作要求'}]
const narrativeFields=computed(()=>isWeekly.value?weeklyNarratives:monthlyNarratives)
const riskLevels=[{value:'general',label:'一般'},{value:'elevated',label:'较大'},{value:'major',label:'重大'}],decisionStatuses=[{value:'pending',label:'待落实'},{value:'in_progress',label:'落实中'},{value:'completed',label:'已完成'}]
function parameters(){return isWeekly.value?{date:selectedDate.value}:{month:selectedMonth.value}}
function blankContent(){return Object.fromEntries(['actual_date','organizer','participants','started_at','ended_at','title','location','host','recorder','absences',...weeklyNarratives.map(item=>item.key),...monthlyNarratives.map(item=>item.key)].map(key=>[key,'']))}
async function load(){loading.value=true;error.value='';try{const [result,config]=await Promise.all([(isWeekly.value?getSafetyWeekly:getSafetyMonthly)(parameters()),getSafetyConfig()]);report.value=result;categories.value=config.categories || [];content.value={...blankContent(),management_issues:[],decisions:[],hazard_ids:[],...clone(result.record?.content || {})};editBaseline.value=JSON.stringify(content.value);editRevision.value=result.record?.revision || 0;editFingerprint.value=result.source_fingerprint || '';sourceConflict.value=false}catch(err){error.value=err.message}finally{loading.value=false}}
function addManagementIssue(){content.value.management_issues.push({type:'',description:'',risk_level:'',responsible_name:'',measure:'',due_date:''})}
function addDecision(){content.value.decisions.push({subject:'',department:'',responsible_name:'',due_date:'',status:'pending',implementation:''})}
async function issueSaved(result){content.value.hazard_ids=[...new Set([...(content.value.hazard_ids || []),result.hazard_id])];showIssue.value=false;uni.showToast({title:'隐患已登记，请保存周报告',icon:'none'})}
async function save(){saving.value=true;try{await(isWeekly.value?saveSafetyWeekly:saveSafetyMonthly)({...parameters(),expected_revision:editRevision.value,source_fingerprint:editFingerprint.value,revision_reason:revisionReason.value,content:content.value});revisionReason.value='';await load();uni.showToast({title:'内容已保存，待签认',icon:'none'})}catch(err){if(err.code===409)sourceConflict.value=true;showError(err)}finally{saving.value=false}}
async function refreshSources(){try{const result=await(isWeekly.value?getSafetyWeekly:getSafetyMonthly)(parameters());report.value=result;editFingerprint.value=result.source_fingerprint || '';sourceConflict.value=false;uni.showToast({title:'统计已刷新，编辑保留，请核对后保存',icon:'none'})}catch(err){showError(err)}}
function reloadContent(){uni.showModal({title:'重新加载台账',content:'当前未保存内容将被服务器版本替换，请先复制需要保留的文字。',success:result=>{if(result.confirm)load()}})}
function preview(){openSafetyPage('print',{kind:props.kind,...parameters()})}
async function exportExcel(){exporting.value=true;try{downloadFile(await exportSafetyDocument({kind:props.kind,...parameters(),format:'xlsx'}))}catch(err){showError(err)}finally{exporting.value=false}}
function changePeriod(value){const apply=()=>{if(isWeekly.value)selectedDate.value=value;else selectedMonth.value=value.slice(0,7);revisionReason.value='';showIssue.value=false;load()};if(JSON.stringify(content.value)!==editBaseline.value){uni.showModal({title:'切换统计周期',content:'当前有未保存的编辑，切换后将不保留。请先保存需要保留的内容。',success:result=>{if(result.confirm)apply()}})}else apply()}
watch(()=>[props.date,props.month],()=>{if(props.date)selectedDate.value=props.date;if(props.month)selectedMonth.value=props.month;load()})
onMounted(load)
</script>
